'use strict';
const $=s=>document.querySelector(s), canvas=$('#world'), ctx=canvas.getContext('2d'), modal=$('#modal'), content=$('#content');
const W=2300,H=1550,STORE='little-day-v1', keys=new Set(), bg=new Image();bg.src='assets/meadow.png';
const initial=()=>({x:970,y:900,hp:100,energy:100,coins:20,day:1,clock:0,grass:0,tokens:0,food:1,rank:0,workRank:0,quest:null,progress:0,completed:0,owned:['ribbon'],wear:{ribbon:false,coat:false,bag:false},cup:false,friendDay:0,huntQuest:null,lastHuntDay:0,huntInProgress:false,materials:{}});
let s=initial();try{const v=JSON.parse(localStorage.getItem(STORE));if(v&&v.version===1){s={...s,...v.state,wear:{...s.wear,...v.state.wear}};s.x=Math.max(100,Math.min(W-100,s.x));s.y=Math.max(100,Math.min(H-100,s.y));}}catch{}
if(s.huntInProgress){s.huntInProgress=false;s.huntQuest=null;s.x=1470;s.y=345;s.hp=Math.max(35,s.hp);}
if(s.hp<=0){s.hp=75;s.energy=Math.max(50,s.energy);s.x=500;s.y=790;}
let dpr=1,sw=innerWidth,sh=innerHeight,zoom=1,cam={x:s.x,y:s.y},time=0,last=0,moving=false,face='front',attackT=0,dodgeT=0,dodgeCD=0,invuln=0,pullT=0,near=null,guideT=0,audioOn=false,audio=null,exam=null,panel='',noticeTimer=0,walkTarget=null;
let particles=[],grass=[],trees=[],monsters=[];let seed=14;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
const spots=[{type:'hunter',x:1460,y:500,name:'토벌 담당 갑옷 씨',r:65},{type:'gate',x:1470,y:270,name:'토벌의 문',r:65},{type:'home',x:500,y:720,name:'내 동굴',r:95},{type:'desk',x:990,y:600,name:'일감 접수처',r:80},{type:'shop',x:1260,y:690,name:'작은 포장마차',r:75},{type:'exam',x:800,y:390,name:'자격증 시험장',r:78},{type:'friend',x:690,y:1000,name:'리본을 좋아하는 이웃',r:30},{type:'spring',x:1400,y:1090,name:'수프가 솟는 샘',r:60}];
for(let i=0;i<32;i++)grass.push({x:760+rand()*530,y:840+rand()*390,type:i%5===0?'flower':'weed',picked:false});
for(let i=0;i<75;i++){let x=80+rand()*(W-160),y=140+rand()*(H-240);if((x<330||x>1630||y<210||y>1330)&&!spots.some(o=>Math.hypot(x-o.x,y-o.y)<150))trees.push({x,y,size:.7+rand()*.8,variant:rand()});}
function spawnMonsters(){monsters=[{x:1780,y:760,ox:1780,oy:760,hp:3,state:'idle',timer:0,hit:0},{x:1940,y:1020,ox:1940,oy:1020,hp:3,state:'idle',timer:0,hit:0}];}spawnMonsters();
function save(){try{localStorage.setItem(STORE,JSON.stringify({version:1,state:s}));}catch{$('.save').textContent='저장 공간이 없어 이번 진행은 저장되지 않습니다';}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
function tone(freq=520,dur=.1){if(!audioOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.065,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur);}catch{}}
function burst(x,y,color,n=9){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*90,vy:-20-Math.random()*70,t:.7,color});}
function resize(){sw=innerWidth;sh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=sw*dpr;canvas.height=sh*dpr;zoom=sw<600?.77:sw<1000?.9:1.13;}addEventListener('resize',resize);resize();
function shape(c,points,fill,stroke='#434638',width=2){c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.lineJoin='round';c.stroke();}}
function ellipse(c,x,y,rx,ry,fill,stroke='#434638',width=2){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.stroke();}}
function line(c,pts,color='#434638',width=2){c.beginPath();c.moveTo(...pts[0]);pts.slice(1).forEach(p=>c.lineTo(...p));c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.stroke();}
function text(c,t,x,y,size=13,color='#394533',align='center'){c.font=`${size}px 'Noto Sans KR',sans-serif`;c.textAlign=align;c.fillStyle=color;c.fillText(t,x,y);}
function shadow(c,x,y,r=25){ellipse(c,x,y,r,r*.35,'#273d3028',null);}
function plant(c,x,y,type='weed',scale=1){c.save();c.translate(x,y);c.scale(scale,scale);line(c,[[0,0],[0,-30]],'#597449',3);if(type==='weed'){shape(c,[[0,-5],[-18,-14],[-21,-30],[-7,-23],[0,-10]],'#81965c');shape(c,[[0,-13],[7,-35],[19,-40],[18,-23],[0,-8]],'#a1b272');shape(c,[[-1,-24],[-6,-39],[-2,-45],[4,-35]],'#859954');}else if(type==='flower'){ellipse(c,-9,-13,10,5,'#8da56a');ellipse(c,9,-10,10,5,'#8da56a');for(let i=0;i<5;i++){let a=i*Math.PI*2/5;ellipse(c,Math.cos(a)*7,-33+Math.sin(a)*7,6,6,'#fff6ce','#877954',1);}ellipse(c,0,-33,4,4,'#dbb557',null);}else{shape(c,[[0,-8],[-23,-18],[-20,-30],[-9,-21],[0,-6]],'#607b61');shape(c,[[0,-9],[10,-31],[20,-32],[24,-18]],'#82966a');line(c,[[-14,-26],[-19,-37]],'#c6b07c',3);}c.restore();}
function character(c,x,y,opts={}){let {scale=1,walk=false,dir='front',wear=s.wear,armor=false,friend=false}=opts;c.save();c.translate(x,y);c.scale(scale,scale);shadow(c,0,0,23);let bob=walk?Math.sin(time*12)*2:Math.sin(time*2)*.7;let step=walk?Math.sin(time*12)*4:0;c.translate(0,bob);if(dir==='left')c.scale(-1,1);if(armor){ellipse(c,-11,-5+step,9,5,'#737e76');ellipse(c,12,-5-step,9,5,'#737e76');shape(c,[[-22,-15],[-25,-48],[0,-57],[25,-48],[22,-14]],'#919e96');ellipse(c,0,-58,29,28,'#aebbb1');shape(c,[[-26,-61],[-18,-77],[13,-83],[27,-62]],'#c3ccc0');line(c,[[-24,-57],[23,-57]],'#4f6156',4);[-13,-5,4,13].forEach(z=>line(c,[[z,-57],[z,-49]],'#47584d',3));ellipse(c,-28,-30,7,14,'#9da99d');ellipse(c,28,-30,7,14,'#9da99d');}else{if(wear.bag&&dir==='front')ellipse(c,17,-26,12,15,'#ae7855');line(c,[[20,-11],[35,-16],[39,-28]],'#74796e',6);ellipse(c,-10,-5+step,9,5,'#a7afa1');ellipse(c,11,-5-step,9,5,'#a7afa1');ellipse(c,0,-32,26,31,'#b8beb0');shape(c,[[-21,-49],[-24,-68],[-10,-57]],'#b8beb0');shape(c,[[14,-56],[25,-69],[24,-46]],'#b8beb0');if(wear.coat){shape(c,[[-23,-31],[23,-31],[27,-8],[-24,-8]],'#6b8996');line(c,[[0,-29],[0,-9]],'#435863',2);ellipse(c,5,-20,1.8,1.8,'#e9d7b4',null);}ellipse(c,-26,-25+(pullT>0?-8:0),6,11,'#b8beb0');ellipse(c,26,-25+(attackT>0?-12:0),6,11,'#b8beb0');if(wear.ribbon||friend){line(c,[[-23,-49],[22,-49]],'#b96756',5);shape(c,[[14,-51],[28,-61],[30,-45]],'#d47d68');shape(c,[[15,-50],[4,-60],[5,-45]],'#d47d68');ellipse(c,15,-50,3,4,'#a85849');}if(wear.bag&&dir!=='front'){shape(c,[[-16,-35],[14,-35],[17,-12],[-17,-12]],'#b7855c');line(c,[[-15,-28],[14,-28]],'#69513c');ellipse(c,0,-22,2,3,'#e7c478');}if(dir!=='back'&&friend){ellipse(c,-8,-38,1.7,2.8,'#414a3d',null);ellipse(c,8,-38,1.7,2.8,'#414a3d',null);line(c,[[-3,-29],[0,-27],[3,-29]],'#414a3d',1.5);}if(attackT>0){c.save();c.translate(27,-29);c.rotate(-1.5+attackT*9);line(c,[[0,5],[0,-39]],'#896b45',5);shape(c,[[-7,-39],[-5,-49],[6,-46],[8,-37]],'#bac0ac');c.restore();}else{line(c,[[27,-17],[34,-43]],'#896b45',3);}}c.restore();}
function tree(c,o){c.save();c.translate(o.x,o.y);c.scale(o.size,o.size);shadow(c,0,0,45);shape(c,[[-10,0],[-7,-95],[8,-95],[12,0]],'#817356');for(let j=0;j<3;j++){let yy=-48-j*33;shape(c,[[-48+j*8,yy],[0,yy-75],[49-j*8,yy], [21,yy+7],[5,yy+3],[-22,yy+9]],j===2?'#718461':'#5a7255','#3f5542',2.5);for(let k=0;k<4;k++)line(c,[[-23+k*12,yy-10],[0,yy-45]],'#4b654b66',1);}c.restore();}
function building(c,o){if(huntWorldObject(c,o))return;c.save();c.translate(o.x,o.y);shadow(c,0,0,o.type==='home'?105:80);if(o.type==='home'){shape(c,[[-115,-6],[-116,-60],[-82,-123],[-22,-149],[56,-130],[109,-70],[108,-4]],'#aaa890','#626754',3);shape(c,[[-63,-2],[-59,-57],[-32,-94],[15,-102],[54,-78],[68,-4]],'#3e493c');shape(c,[[-45,-2],[-39,-46],[-14,-74],[15,-78],[41,-49],[46,-2]],'#273c34',null);line(c,[[-107,-49],[-70,-72],[-78,-117]],'#838770');line(c,[[61,-117],[57,-88],[92,-68]],'#838770');shape(c,[[-31,-8],[25,-11],[40,-2],[-37,2]],'#c2a882');ellipse(c,82,-30,10,13,'#e5c378');line(c,[[82,-42],[82,-51]],'#685b3c');if(s.cup){ellipse(c,-79,-16,10,4,'#cccab3');ellipse(c,-79,-27,7,9,'#ece7d2');}}else if(o.type==='friend'){character(c,0,0,{friend:true,wear:{ribbon:true},walk:false});}else if(o.type==='spring'){ellipse(c,0,-3,62,25,'#9eaa8c');ellipse(c,0,-8,53,20,'#d4b875');ellipse(c,0,-11,41,13,'#e6c67f',null);for(let j=0;j<3;j++)line(c,[[-18+j*18,-15],[-23+j*18,-30-Math.sin(time*2+j)*5],[-17+j*18,-40]],'#fff8d689',2);}else{let isShop=o.type==='shop',isExam=o.type==='exam';shape(c,[[-72,0],[-72,-77],[72,-77],[72,0]],'#b0a17c');shape(c,[[-83,-76],[-67,-125],[66,-125],[86,-76]],isShop?'#b36d50':isExam?'#758b8c':'#7b8a63');for(let k=0;k<6;k++){let xx=-73+k*27;shape(c,[[xx,-78],[xx+10,-123],[xx+22,-123],[xx+25,-78]],'#ece3be',null);}line(c,[[-72,-79],[-72,-5]],'#645b42',5);line(c,[[72,-79],[72,-5]],'#645b42',5);character(c,8,-13,{armor:true,scale:.8});shape(c,[[-79,-37],[79,-37],[79,-5],[-79,-5]],'#baa982');line(c,[[-72,-31],[71,-31]],'#e1cea3',2);if(isShop){ellipse(c,-39,-41,15,6,'#f1e3be');ellipse(c,-39,-44,12,4,'#c89c5a',null);}else{shape(c,[[-56,-62],[-23,-64],[-21,-39],[-55,-37]],'#f2ead0');for(let j=0;j<3;j++)line(c,[[-49,-56+j*6],[-29,-57+j*6]],'#a99876',1);}}c.restore();label(o.name,o.x,o.y+27);}
function label(t,x,y){ctx.font="13px 'Noto Sans KR'";let width=ctx.measureText(t).width+20;ctx.fillStyle='#fcf6e4e8';ctx.beginPath();ctx.roundRect(x-width/2,y-16,width,24,5);ctx.fill();text(ctx,t,x,y,12);}
function enemy(c,m){c.save();c.translate(m.x,m.y);shadow(c,0,0,32);let b=Math.sin(time*4)*2;shape(c,[[-29,-13],[-34,-35],[-24,-55],[-9,-47],[0,-65],[14,-48],[28,-55],[35,-31],[27,-9]],m.hit>0?'#efc6a3':m.state==='windup'?'#bd8866':'#777e64','#424d3e',3);ellipse(c,-15,-30+b,8,10,'#e8e2bd');ellipse(c,15,-30+b,8,10,'#e8e2bd');ellipse(c,-14,-28+b,2.5,4,'#3d493e',null);ellipse(c,14,-28+b,2.5,4,'#3d493e',null);line(c,[[-9,-12],[0,-16],[9,-12]],'#3c493c',2);if(m.state==='windup')text(c,'!',0,-82,30,'#b04436');if(m.hp<3){c.fillStyle='#352e';c.fillRect(-23,-73,46,5);c.fillStyle='#c58964';c.fillRect(-23,-73,46*m.hp/3,5);}c.restore();}
function render(){if(arena){renderArena();return;}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,sw,sh);ctx.fillStyle='#aab38a';ctx.fillRect(0,0,sw,sh);ctx.save();ctx.translate(sw/2,sh/2+50);ctx.scale(zoom,zoom);ctx.translate(-cam.x,-cam.y);if(bg.complete&&bg.naturalWidth)ctx.drawImage(bg,0,0,W,H);else{ctx.fillStyle='#a2b183';ctx.fillRect(0,0,W,H);}let forestShade=ctx.createLinearGradient(1530,0,2050,0);forestShade.addColorStop(0,'#29433900');forestShade.addColorStop(1,'#29433945');ctx.fillStyle=forestShade;ctx.fillRect(1530,0,770,H);for(let i=0;i<grass.length;i++){let g=grass[i];if(!g.picked){shadow(ctx,g.x,g.y,10);plant(ctx,g.x,g.y,g.type,.8);}}let draw=[...trees.map(o=>({y:o.y,fn:()=>tree(ctx,o)})),...spots.map(o=>({y:o.y,fn:()=>building(ctx,o)})),...monsters.filter(o=>o.hp>0).map(o=>({y:o.y,fn:()=>enemy(ctx,o)})),{y:s.y,fn:()=>{if(invuln>0&&Math.floor(time*12)%2)ctx.globalAlpha=.45;character(ctx,s.x,s.y,{walk:moving,dir:face});ctx.globalAlpha=1;drawSpeech(ctx,s.x,s.y);}}];draw.sort((a,b)=>a.y-b.y);draw.forEach(o=>o.fn());if(guideT>0){let target=questTarget(),dx=target.x-s.x,dy=target.y-s.y,d=Math.hypot(dx,dy);if(d>90){ctx.save();ctx.translate(s.x+dx/d*85,s.y+dy/d*85);ctx.rotate(Math.atan2(dy,dx));shape(ctx,[[18,0],[-9,-9],[-4,0],[-9,9]],'#fff3ba','#778554',2);ctx.restore();}}for(const p of particles)ellipse(ctx,p.x,p.y,3,3,p.color,null);if(near&&near.type==='plant'){ctx.strokeStyle='#f9f2c5';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(near.ref.x,near.ref.y,23,11,0,0,7);ctx.stroke();}ctx.restore();let night=Math.max(0,(s.clock-250)/170)*.25;if(night){ctx.fillStyle=`rgba(30,43,76,${night})`;ctx.fillRect(0,0,sw,sh);}let v=ctx.createRadialGradient(sw/2,sh/2,sh*.25,sw/2,sh/2,Math.max(sw,sh)*.7);v.addColorStop(0,'#253b2100');v.addColorStop(1,'#263b2133');ctx.fillStyle=v;ctx.fillRect(0,0,sw,sh);}
function collides(x,y){if(x<90||x>W-90||y<100||y>H-90)return true;return spots.filter(o=>!['friend','spring'].includes(o.type)).some(o=>Math.abs(x-o.x)<o.r&&y>o.y-85&&y<o.y+8)||trees.some(o=>Math.hypot((x-o.x), (y-o.y)*1.5)<17*o.size);}
function closest(){let best=null,d=100;for(const o of spots){let dd=Math.hypot(s.x-o.x,s.y-(o.y+35));if(dd<d){d=dd;best={type:o.type,ref:o};}}for(const g of grass){if(g.picked)continue;let dd=Math.hypot(s.x-g.x,s.y-g.y);if(dd<Math.min(d,65)){d=dd;best={type:'plant',ref:g};}}return best;}
function questTarget(){if(s.huntQuest)return spots.find(o=>o.type==='gate');if(s.quest==='weed'&&s.progress<5)return{x:1010,y:1050};if(s.quest==='hunt'&&s.progress<1)return{x:1780,y:760};return s.huntQuest?spots.find(o=>o.type==='gate'):spots.find(o=>o.type==='desk');}
function ui(){if(arena){updateHuntUI();return;} $('#hpText').textContent=`${Math.ceil(s.hp)} / 100`;$('#energyText').textContent=`${Math.ceil(s.energy)} / 100`;$('#hpBar').style.width=s.hp+'%';$('#energyBar').style.width=s.energy+'%';$('#coins').textContent=s.coins;$('#rank').textContent=s.rank?`제초 ${s.rank}급`:'제초 무급';$('#day').textContent=`${s.day}일째`;$('#time').textContent=s.clock<180?'오전 · 맑음':s.clock<300?'오후 · 산들바람':'저녁 · 귀가할 시간';$('#sun').textContent=s.clock<300?'☀':'☾';$('#place').textContent=s.x>1600?'조심스러운 숲 입구':s.y>900?'바람 부는 들판':s.x<650?'나의 작은 동굴':'갑옷 씨의 상점가';let title='첫 일감을 찾아서',desc='마을 가운데 접수처의 갑옷 씨와 이야기해 보세요.',prog='';if(s.quest==='weed'){title='들판을 말끔하게';desc='뾰족잎 잡초 5개를 뽑으세요. 흰 꽃이 핀 풀은 남겨 주세요.';prog=`${Math.min(s.progress,5)} / 5개 · 보수 ${s.rank?40:30}코인`;}else if(s.quest==='hunt'){title='숲 입구의 소란';desc='숲에서 덤불 괴물과 마주치면 턴제 전투가 시작돼요.';prog=`${Math.min(s.progress,1)} / 1마리 · 보수 50코인`;}else if(s.completed){title='오늘은 무엇을 할까';desc='새 일감, 제초 급수 시험, 작은 쇼핑. 하고 싶은 일을 골라 보세요.';prog=`완료한 일감 ${s.completed}개`;}if(s.huntQuest){title=HUNTS[s.huntQuest].name+' 토벌';desc='북쪽 토벌의 문에서 출정하세요. WASD 이동 · J 공격 · Space 회피';prog=s.lastHuntDay===s.day?'오늘 출정 완료 · 다음 날 다시 도전':'오늘 출정 가능 · 행동력 20';}$('#questTitle').textContent=title;$('#questText').textContent=desc;$('#questProgress').textContent=prog;$('#guide').textContent=s.quest?'목표 방향 보기':'접수처 방향 보기';near=closest();let prompt='';if(near){let t=near.type;prompt=t==='plant'?(near.ref.type==='weed'?'E · 잡초 뽑기':'흰 꽃 · 남겨 두는 풀'):t==='home'?'E · 동굴에서 쉬기':t==='spring'?'E · 따뜻한 수프 마시기':`E · ${near.ref.name}`;}$('#prompt').textContent=prompt;$('#prompt').style.display=prompt&&!modal.open?'block':'none';}
function update(dt){time+=dt;if(arena){updateArena(dt);return;}if(modal.open){if(exam&&exam.running){if(!exam.practice){exam.left-=dt;if(exam.left<=0)finishExam();else $('#examTime').textContent=Math.ceil(exam.left)+'초';}}return;}s.clock=Math.min(420,s.clock+dt);attackT=Math.max(0,attackT-dt);dodgeT=Math.max(0,dodgeT-dt);dodgeCD=Math.max(0,dodgeCD-dt);pullT=Math.max(0,pullT-dt);invuln=Math.max(0,invuln-dt);guideT=Math.max(0,guideT-dt);let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(dx||dy)walkTarget=null;else if(walkTarget){const tx=walkTarget.x-s.x,ty=walkTarget.y-s.y;if(Math.hypot(tx,ty)<8)walkTarget=null;else{dx=tx;dy=ty;}}moving=!!(dx||dy);if(moving){let l=Math.hypot(dx,dy),speed=dodgeT>0?380:150;dx=dx/l*speed*dt;dy=dy/l*speed*dt;let moved=false;if(!collides(s.x+dx,s.y)){s.x+=dx;moved=true;}if(!collides(s.x,s.y+dy)){s.y+=dy;moved=true;}if(!moved)walkTarget=null;if(Math.abs(dx)>Math.abs(dy)*.8)face=dx<0?'left':'right';else face=dy<0?'back':'front';}cam.x+=(s.x-cam.x)*Math.min(1,dt*5);cam.y+=(s.y-cam.y)*Math.min(1,dt*5);encounterCooldown=Math.max(0,encounterCooldown-dt);for(const m of monsters){if(m.hp>0&&Math.hypot(m.x-s.x,m.y-s.y)<90&&encounterCooldown<=0){startBattle(m);break;}}particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=100*dt;p.t-=dt;});particles=particles.filter(p=>p.t>0);}
function loop(now){let dt=Math.min(.05,(now-last)/1000||0);last=now;update(dt);render();ui();requestAnimationFrame(loop);}requestAnimationFrame(loop);setInterval(save,5000);addEventListener('pagehide',save);
function interact(){if(arena){arenaInteract();return;}if(modal.open)return;near=closest();if(!near){toast('대상 가까이에서 E를 눌러 주세요.');return;}let o=near.ref;if(near.type==='plant'){if(o.type!=='weed'){toast('이건 꽃풀이에요. 뽑지 않고 남겨 둘게요.');return;}if(!spendEnergy(3))return;o.picked=true;s.grass++;pullT=.4;if(s.quest==='weed')s.progress++;burst(o.x,o.y-10,'#e8dfa1');tone(630);save();if(s.quest==='weed'&&s.progress===5)toast('잡초 5개 완료! 접수처에서 보수를 받으세요.');return;}openPanel(near.type);}
function attack(){if(arena){huntAttack();return;}if(modal.open)return;const m=monsters.find(m=>m.hp>0&&Math.hypot(m.x-s.x,m.y-s.y)<130);if(m)startBattle(m);else toast('몬스터 가까이 다가가면 턴제 전투가 시작돼요.');}
function dodge(){if(arena){huntDodge();return;}if(modal.open||dodgeCD>0)return;if(!spendEnergy(4))return;dodgeT=.24;dodgeCD=.8;invuln=.35;}
function show(html,p=''){panel=p;walkTarget=null;content.innerHTML=html;if(!modal.open)modal.showModal();keys.clear();$('#close').focus();}
canvas.addEventListener('pointermove',e=>{if(arena)arenaPointer(e);});
canvas.addEventListener('pointerdown',e=>{if(arena){arenaPointer(e,true);return;}if(modal.open)return;walkTarget={x:(e.clientX-sw/2)/zoom+cam.x,y:(e.clientY-sh/2-50)/zoom+cam.y};canvas.focus();});
function close(){if(battle){toast('전투 메뉴에서 행동이나 도망가기를 골라 주세요.');return;}if(exam?.running){exam.running=false;toast('시험을 중단했어요. 언제든 다시 도전할 수 있어요.');}exam=null;modal.close();panel='';keys.clear();canvas.focus();save();}
$('#close').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();close();});
const head=(e,t,p='')=>`<span class="eyebrow">${e}</span><h1>${t}</h1>${p?`<p>${p}</p>`:''}`;
function openPanel(type){if(arena||battle||exam?.running)return;if(type==='hunter')return huntDesk();if(type==='gate')return huntGate();switch(type){case'desk':{let done=s.quest&&(s.quest==='weed'?s.progress>=5:s.progress>=1);show(head('갑옷 씨의 접수처','오늘도 무리하지 말고.',done?'잘 해냈구나. 여기 오늘의 보수야.':'가까운 들판부터 시작해도 좋아. 준비가 됐다면 숲에도 일이 있단다.')+(s.quest?`<div class="note">진행 중: ${s.quest==='weed'?'잡초 5개 뽑기':'덤불 괴물 1마리 토벌'} · ${s.progress}/${s.quest==='weed'?5:1}</div><div class="actions">${done?'<button class="primary" data-act="claim">보수 받기</button>':'<button data-act="close">계속 일하러 가기</button>'}</div>`:`<div class="cardgrid"><div class="item"><h3>들판 제초</h3><p>잡초 5개 · 안전한 일감<br>보수 ${s.rank?40:30}코인</p><button class="primary" data-act="quest-weed">일감 받기</button></div><div class="item"><h3>숲에서의 조우</h3><p>몬스터에게 다가가면 턴제 전투<br>승리 보상 20코인 + 증표</p><button data-act="forest-guide">숲 방향 알아보기</button></div></div>`),'desk');break;}case'home':show(head('나의 동굴','돌아왔구나.',`작은 이불과 ${s.cup?'새로 산 찻잔이':'낡은 상자가'} 기다리고 있어요. 푹 자면 체력과 행동력이 모두 회복됩니다.`)+`<div class="note">${s.day}일째 · 오늘도 잘 살아냈어요.<br>잠을 자면 들판의 잡초와 숲의 괴물이 다시 나타납니다.</div><div class="actions"><button class="primary" data-act="sleep">푹 자고 다음 날 맞기</button><button data-act="wardrobe">옷 갈아입기</button></div>`,'home');break;case'shop':shop();break;case'exam':examMenu();break;case'wardrobe':wardrobe();break;case'bag':show(head('나의 가방','오늘 모은 것들')+`<div class="cardgrid"><div class="item"><h3>따뜻한 도시락 × ${s.food}</h3><p>체력 +15 · 행동력 +35</p><button data-act="eat" ${s.food?'':'disabled'}>먹기</button></div><div class="item"><h3>뽑은 잡초 × ${s.grass}</h3><p>오늘도 부지런히 일한 흔적.</p></div><div class="item"><h3>토벌 증표 × ${s.tokens}</h3><p>숲에서 용기를 낸 증거.</p></div><div class="item"><h3>나의 자격증</h3><p>제초: ${s.rank?s.rank+'급':'아직 없음'}<br>아르바이트: ${s.workRank?s.workRank+'급':'아직 없음'}</p></div></div>`,'bag');break;case'book':book();break;case'map':show(head('마을 안내도','어디로 가볼까?','현재 위치는 붉은 점이에요. 동쪽 숲에는 괴물이 살아요.')+'<canvas id="mapCanvas" class="mapcanvas" width="600" height="320"></canvas><div class="note">WASD / 방향키 이동 · E 상호작용<br>Space 가까운 몬스터 조우 · Shift + 이동 빠른 걸음 · C 옷장 · B 교재</div>','map');drawMap();break;case'friend':show(head('들판의 이웃','“오늘은 뭐 했어?”','“나는 아까 풀을 잘못 뽑았어… 그래도 내일 다시 해보려고. 같이 도시락 먹을래?”')+`<div class="actions"><button class="primary" data-act="share" ${s.food&&s.friendDay!==s.day?'':'disabled'}>${s.friendDay===s.day?'오늘은 함께 먹었어요':'도시락 나누기 · 1개'}</button><button data-act="close">손 흔들고 가기</button></div>`,'friend');break;case'spring':show(head('솟아나는 작은 행복','따뜻한 수프 한 컵','어디서 나오는지는 모르지만, 오늘은 고소한 냄새가 나요. 천천히 마시고 쉬어 가세요.')+'<div class="actions"><button class="primary" data-act="soup">무료 수프 마시기 · 행동력 +25</button></div>','spring');break;}}
function shop(){show(head('갑옷 씨의 작은 가게','수고한 날의 선물',`가진 돈 ${s.coins}코인 · 구매한 옷은 바로 입을 수 있어요.`)+`<div class="cardgrid">${[['food','따뜻한 도시락','체력 +15 · 행동력 +35',10],['coat','푸른 작업복','들판에 어울리는 가벼운 옷',35],['bag','밤색 가방','등에 메고 다니는 작은 가방',45],['cup','작은 찻잔','동굴 앞에 놓이는 나만의 물건',50]].map(([id,n,d,p])=>`<div class="item"><h3>${n}</h3><p>${d}</p><button data-buy="${id}" ${id!=='food'&&(s.owned.includes(id)||id==='cup'&&s.cup)?'disabled':''}>${id!=='food'&&(s.owned.includes(id)||id==='cup'&&s.cup)?'구매 완료':p+'코인 · 구매'}</button></div>`).join('')}</div>`,'shop');}
function wardrobe(){show(head('작은 옷장','오늘은 이걸 입을까?','장비는 걷거나 일할 때도 그대로 보여요. 머리띠는 처음부터 가지고 있어요.')+'<canvas id="outfit" class="outfit-preview" width="240" height="240"></canvas>'+`<div class="cardgrid">${[['ribbon','붉은 머리띠'],['coat','푸른 작업복'],['bag','밤색 가방']].map(([id,n])=>`<div class="item"><h3>${n}</h3><button data-wear="${id}" ${s.owned.includes(id)?'':'disabled'}>${!s.owned.includes(id)?'포장마차에서 구매':s.wear[id]?'벗기':'입기'}</button></div>`).join('')}</div>`,'wardrobe');const c=$('#outfit').getContext('2d');character(c,120,180,{scale:2,dir:s.wear.bag?'back':'front'});}
function book(){show(head('갑옷 씨의 그림 교재','풀부터 천천히 알아보자.','시험은 배운 그림에서 나와요. 처음에는 시간 걱정 없이 연습해 보세요.')+`<div class="bookrow"><canvas data-plant="weed" width="90" height="90"></canvas><div><b>뾰족잎 잡초 → Space로 뽑기</b><p>끝이 뾰족하고 위로 갈라지는 잎. 꽃이 없어요.</p></div></div><div class="bookrow"><canvas data-plant="flower" width="90" height="90"></canvas><div><b>흰 꽃풀 → S로 보존하기</b><p>둥근 잎과 하얀 꽃. 들판에 남겨 주세요.</p></div></div><div class="note" style="margin-top:16px">아르바이트 시험: 주문표의 품목과 맨 아래 물건이 같으면 Space로 전달, 다르면 S로 넘겨요.<br>제초·아르바이트 모두 A / D로 줄을 고릅니다.</div><div class="actions"><button class="primary" data-act="practice-weed">제초 연습하기</button><button data-act="practice-work">아르바이트 연습</button></div>`,'book');drawPlants();}
function drawPlants(){document.querySelectorAll('[data-plant]').forEach(el=>{const c=el.getContext('2d');plant(c,el.width/2,el.height-10,el.dataset.plant,1.4);});}
function examMenu(){show(head('자격증 접수처','조금씩, 더 능숙하게.','연습은 무료예요. 실전에서는 정해진 시간 안에 정확하게 처리해 주세요.')+`<div class="cardgrid"><div class="item"><h3>제초 자격 시험</h3><p>현재 ${s.rank?s.rank+'급':'무급'} · 잡초와 꽃풀 구별<br>합격하면 제초 보수 상승</p><button data-act="practice-weed">연습</button> <button class="primary" data-act="exam-weed">${s.rank===3?'3급 재도전':(s.rank?s.rank-1:5)+'급 도전'}</button></div><div class="item"><h3>아르바이트 자격 시험</h3><p>현재 ${s.workRank?s.workRank+'급':'무급'} · 주문 분류<br>합격 후 시험장 모의 근무 해금</p><button data-act="practice-work">연습</button> <button class="primary" data-act="exam-work">${s.workRank===3?'3급 재도전':(s.workRank?s.workRank-1:5)+'급 도전'}</button></div></div>${s.workRank?'<button data-act="shift-work">모의 근무 · 성공 시 25코인</button>':''}<div class="note" style="margin-top:15px">5급: 40초 · 정답 20개 · 실수 4회 이하<br>4급: 40초 · 정답 28개 · 실수 3회 이하<br>3급: 40초 · 정답 36개 · 실수 3회 이하<br>시험 중에는 마을의 시간이 멈춥니다.</div>`,'exam');}
function drawMap(){const c=$('#mapCanvas').getContext('2d');c.fillStyle='#dce3bd';c.fillRect(0,0,600,320);c.fillStyle='#8eaa7b';c.fillRect(420,0,180,320);spots.forEach(o=>{let x=o.x/W*580+10,y=o.y/H*290+10;ellipse(c,x,y,5,5,'#657454',null);text(c,o.name,x,y-12,11);});ellipse(c,s.x/W*580+10,s.y/H*290+10,6,6,'#b7634e','#fff',2);text(c,'괴물 서식지',490,170,13);}
const products=[{name:'푸딩',icon:'🍮'},{name:'라면',icon:'🍜'},{name:'차',icon:'🍵'}];
function startExam(kind,practice=false,shift=false){const current=kind==='weed'?s.rank:s.workRank,rank=Math.max(3,current?current-1:5),n=rank===5?2:3;exam={kind,practice,shift,rank,n,selected:0,left:practice?9999:40,score:0,mistakes:0,target:rank===5?20:rank===4?28:36,maxMistakes:rank===5?4:3,lanes:[],order:Math.floor(Math.random()*3),running:false};for(let i=0;i<n;i++)exam.lanes.push(Array.from({length:4},()=>nextCard()));show(head(practice?'마음 편한 연습':'실기 시험',kind==='weed'?'뽑을까, 남겨둘까?':'주문에 맞게 전달해요',kind==='weed'?'뾰족잎 잡초는 뽑고, 흰 꽃풀은 남겨요.':'주문표와 같은 물건만 전달하고 나머지는 넘겨요.')+`<div class="note">A / D 또는 ← / → 줄 선택<br>Space: ${kind==='weed'?'잡초 뽑기':'주문 전달'} · S / ↓: ${kind==='weed'?'꽃풀 보존':'다른 물건 넘기기'}<br>${practice?'시간제한 없이 연습할 수 있어요.':`40초 안에 ${exam.target}개 정답 · 실수 ${exam.maxMistakes}회 이하`}</div><div class="actions"><button class="primary" data-act="start-exam">${practice?'연습 시작':'시험 시작'}</button></div>`,'exam-ready');}
function nextCard(){return exam.kind==='weed'?(Math.random()<.57?'weed':'flower'):Math.floor(Math.random()*3);}
function examScreen(){if(!exam)return;show(head(exam.practice?'연습 중':`${exam.rank}급 ${exam.shift?'모의 근무':'실기 시험'}`,exam.kind==='weed'?'뽑을까, 남겨둘까?':'주문을 부탁해요')+`<div class="examhead"><b id="examTime">${exam.practice?'∞':Math.ceil(exam.left)+'초'}</b><span id="examScore">정답 ${exam.score}${exam.practice?'':' / '+exam.target} · 실수 ${exam.mistakes}${exam.practice?'':' / '+exam.maxMistakes}</span></div><div class="note" id="examRule">${exam.kind==='weed'?'뾰족잎은 뽑기 · 흰 꽃은 보존':`주문: ${products[exam.order].icon} ${products[exam.order].name}`}</div><div class="examFeedback" id="feedback">맨 아래 카드부터 처리해요</div><div class="examboard">${exam.lanes.map((l,i)=>`<div class="lane ${i===exam.selected?'selected':''}" data-lane="${i}" role="button" tabindex="0" aria-label="${i+1}번 줄 선택">${l.map(v=>`<div class="plantcard">${exam.kind==='weed'?`<canvas data-plant="${v}" width="90" height="90"></canvas>`:`<span style="font-size:32px" aria-label="${products[v].name}">${products[v].icon}</span>`}</div>`).join('')}</div>`).join('')}</div><div class="exam-actions"><button class="primary" data-act="answer-yes">${exam.kind==='weed'?'뽑기':'전달'} <kbd>Space</kbd></button><button data-act="answer-no">${exam.kind==='weed'?'보존':'넘기기'} <kbd>S</kbd></button></div><p style="text-align:center;font-size:12px;margin-bottom:0">A / D · 줄 선택　|　맨 아래부터 처리</p>`,'exam-running');drawPlants();document.querySelectorAll('.lane').forEach(el=>el.addEventListener('keydown',ev=>{if(ev.key==='Enter'){ev.preventDefault();chooseLane(+el.dataset.lane);}}));}
function chooseLane(i){if(!exam?.running)return;exam.selected=(i+exam.n)%exam.n;document.querySelectorAll('.lane').forEach((el,j)=>el.classList.toggle('selected',j===exam.selected));}
function answer(yes){if(!exam?.running)return;let lane=exam.lanes[exam.selected],v=lane.at(-1),correct=yes===(exam.kind==='weed'?v==='weed':v===exam.order);if(correct){exam.score++;tone(620,.06);}else{exam.mistakes++;tone(170,.1);}lane.pop();lane.unshift(nextCard());if(exam.kind==='work'&&yes&&correct)exam.order=Math.floor(Math.random()*3);if(!exam.practice&&(exam.score>=exam.target||exam.mistakes>exam.maxMistakes)){finishExam();return;}examScreen();$('#feedback').textContent=correct?'잘했어요!':exam.kind==='weed'?(v==='weed'?'뾰족잎 잡초는 뽑아야 해요.':'흰 꽃풀은 남겨 주세요.'):'주문표의 품목을 다시 확인해요.';$('#feedback').className='examFeedback '+(correct?'pass':'danger');$('.examboard').classList.add(correct?'correct':'wrong');setTimeout(()=>$('.examboard')?.classList.remove('correct','wrong'),130);}
function finishExam(){if(!exam)return;const e=exam;e.running=false;let pass=e.score>=e.target&&e.mistakes<=e.maxMistakes;let reward='';if(pass){if(e.shift){s.coins+=25;reward='근무 보수 25코인을 받았어요.';}else if(e.kind==='weed'){s.rank=s.rank?Math.min(s.rank,e.rank):e.rank;reward='제초 일감의 보수가 40코인으로 올랐어요.';}else{s.workRank=s.workRank?Math.min(s.workRank,e.rank):e.rank;reward='시험장에서 모의 근무를 할 수 있어요.';}tone(880,.25);save();}show(head('시험 결과',pass?'해냈어요, 합격!':'조금 더 연습해 볼까요?')+`<div class="receipt">${pass?'合格':'다음 기회에'}</div><div class="note">정답 ${e.score} / ${e.target} · 실수 ${e.mistakes} / ${e.maxMistakes}<br>${pass?reward:'틀려도 괜찮아요. 교재와 연습은 언제든 볼 수 있어요.'}</div><div class="actions"><button class="primary" data-act="exam">접수처로</button><button data-act="practice-${e.kind}">연습하기</button></div>`,'exam-result');exam=null;}
content.addEventListener('click',e=>{const b=e.target.closest('button,[data-lane]');if(!b||b.disabled)return;if(b.dataset.battle){battleAction(b.dataset.battle);return;}if(b.dataset.lane!==undefined){chooseLane(+b.dataset.lane);return;}if(b.dataset.wear){s.wear[b.dataset.wear]=!s.wear[b.dataset.wear];save();wardrobe();return;}if(b.dataset.buy){let id=b.dataset.buy,p={food:10,coat:35,bag:45,cup:50}[id];if(s.coins<p){toast('코인이 조금 더 필요해요.');return;}s.coins-=p;if(id==='food')s.food++;else if(id==='cup')s.cup=true;else{s.owned.push(id);s.wear[id]=true;}tone(760);save();shop();toast(id==='food'?'도시락을 가방에 넣었어요.':id==='cup'?'동굴 앞에 작은 찻잔을 놓았어요.':'새 옷을 바로 입었어요!');return;}let a=b.dataset.act;if(!a)return;if(a.startsWith('hunt-accept-'))return acceptHunt(a.slice(12));if(a==='hunt-start')return startHunt();if(a==='rescue-yes')return beginRescue('철수를 선택했어요.');if(a==='close')return close();if(a==='forest-guide'){close();toast('동쪽으로 걸어가면 어두운 숲이 나와요. M으로 지도를 볼 수 있어요.');return;}if(a==='start-exam'){exam.running=true;examScreen();return;}if(a.startsWith('answer-'))return answer(a==='answer-yes');if(a.startsWith('practice-'))return startExam(a.slice(9),true);if(a.startsWith('exam-'))return startExam(a.slice(5));if(a==='shift-work')return startExam('work',false,true);if(a.startsWith('quest-')){s.quest=a.slice(6);s.progress=0;guideT=12;if(s.quest==='weed'&&grass.filter(g=>!g.picked&&g.type==='weed').length<5)grass.forEach(g=>g.picked=false);if(s.quest==='hunt'&&monsters.every(m=>m.hp<=0))spawnMonsters();close();toast('일감을 받았어요. 밝은 화살표 방향으로 가보세요.');return;}if(a==='claim'){s.coins+=s.quest==='weed'?(s.rank?40:30):50;s.quest=null;s.progress=0;s.completed++;close();tone(820,.2);toast('보수를 받았어요. 오늘도 수고했어요!');return;}if(a==='sleep'){s.day++;s.clock=0;s.hp=100;s.energy=100;s.x=500;s.y=790;grass.forEach(g=>g.picked=false);spawnMonsters();close();toast('새로운 아침이에요. 몸과 마음이 가벼워졌어요.');return;}if(a==='soup'){s.energy=Math.min(100,s.energy+25);close();tone(520);toast('따뜻하다… 행동력 +25');return;}if(a==='eat'&&s.food){s.food--;s.energy=Math.min(100,s.energy+35);s.hp=Math.min(100,s.hp+15);save();openPanel('bag');tone(680);return;}if(a==='share'&&s.food&&s.friendDay!==s.day){s.food--;s.friendDay=s.day;s.energy=Math.min(100,s.energy+40);s.hp=Math.min(100,s.hp+20);close();toast('“같이 먹으니까 더 맛있다.” 체력 +20 · 행동력 +40');return;}openPanel(a);});
addEventListener('keydown',e=>{const k=({KeyW:'w',KeyA:'a',KeyS:'s',KeyD:'d',KeyE:'e',KeyI:'i',KeyC:'c',KeyB:'b',KeyM:'m',KeyJ:'j',KeyF:'f',Space:' ',ShiftLeft:'shift',ShiftRight:'shift'})[e.code]||e.key.toLowerCase();if(arena){if(e.target?.matches?.('input,textarea,select'))return;if(modal.open)return;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);arena.pointerAim=false;if(e.repeat)return;if(k===' '||k==='shift')huntDodge();if(k==='j')huntAttack();if(k==='f')huntEat();if(k==='e')arenaInteract();return;}if([' ','arrowup','arrowdown','arrowleft','arrowright','tab'].includes(k)&&k!=='tab')e.preventDefault();if(exam?.running){if(e.repeat)return;if(k==='a'||k==='arrowleft')chooseLane(exam.selected-1);if(k==='d'||k==='arrowright')chooseLane(exam.selected+1);if(k===' ')answer(true);if(k==='s'||k==='arrowdown')answer(false);return;}if(modal.open)return;keys.add(k);if(e.repeat)return;if(k==='e')interact();if(k===' ')attack();if(k==='shift')dodge();if(k==='i')openPanel('bag');if(k==='c')openPanel('wardrobe');if(k==='b')openPanel('book');if(k==='m')openPanel('map');});addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());if(e.code?.startsWith('Key'))keys.delete(e.code.slice(3).toLowerCase());});addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();last=performance.now();});
$('.toolbar').onclick=e=>{const b=e.target.closest('[data-panel]');if(b)openPanel(b.dataset.panel);};$('#guide').onclick=()=>{guideT=15;toast('캐릭터 옆 화살표가 목표를 가리켜요.');};$('#help').onclick=()=>show(head('작은 하루 · 쉬움','서두르지 않아도 괜찮아요.','작은 주민이 되어 일하고, 맛있는 것을 먹고, 내일을 준비해 보세요.')+'<div class="note">① 접수처에서 제초 일감 받기<br>② 들판에서 E로 잡초 5개 뽑기<br>③ 돌아와 보수 받고 포장마차에서 쇼핑<br>④ 교재로 연습하고 시험장에 도전하기<br>⑤ 동쪽 숲의 몬스터에게 다가가 턴제 전투<br><br>WASD / 방향키 이동 · E 행동 · Space 공격<br>Shift + 이동 회피 · I 가방 · C 옷장 · B 교재 · M 지도<br><br>게임은 끝없이 이어집니다. 플레이어 괴물화는 없고, 패배해도 물건을 잃지 않아요. 진행은 이 브라우저에 저장됩니다.</div><div class="actions"><button class="primary" data-act="close">들판으로 돌아가기</button></div>','help');$('#sound').onclick=()=>{audioOn=!audioOn;$('#sound').style.opacity=audioOn?1:.5;$('#sound').setAttribute('aria-label',audioOn?'효과음 끄기':'효과음 켜기');tone();};
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);});b.addEventListener('pointerup',()=>keys.delete(b.dataset.key));b.addEventListener('pointercancel',()=>keys.delete(b.dataset.key));});$('#rescueButton').onclick=askRescue;$('#huntEat').onclick=huntEat;
$('#huntAdmin').addEventListener('input',e=>{if(e.target.dataset.tune)setHuntTune(e.target.dataset.tune,Number(e.target.value));if(e.target.dataset.switch)setHuntSwitch(e.target.dataset.switch,e.target.checked);});
$('#huntAdmin').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.reset)resetHunt(b.dataset.reset);if(b.dataset.huntConfig&&arena){for(const [k,v]of Object.entries(HUNT_PRESETS[b.dataset.huntConfig]))setHuntTune(k,v);buildHuntAdmin();}});
$('#touchInteract').onclick=interact;$('#touchAttack').onclick=attack;$('#touchDodge').onclick=dodge;
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_village_progress',description:'Read the current local game day, resources, active job and certificates.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>({day:s.day,coins:s.coins,hp:s.hp,energy:s.energy,job:s.quest,progress:s.progress,weedingRank:s.rank,workRank:s.workRank})});}catch{}}
ui();toast('작은 하루에 오신 걸 환영해요. WASD로 걷고, E로 이야기해요.');
